    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '301: "Urine Specific Gravity" of 1.010 (fixed) across multiple samples suggests:', '["Normal concentration", "Chronic Renal Failure (isosthenuria)", "Dehydration", "Diabetes insipidus"]', 1, 'The kidney has lost its ability to concentrate or dilute urine.'),
    (v_topic_id, '302: "Urine Dipstick" is most sensitive for which type of protein?', '["Bence-Jones proteins", "Albumin", "Globulin", "Hemoglobin"]', 1, 'It often misses non-albumin proteins, which is why a sulfosalicylic acid (SSA) test is used if multiple myeloma is suspected.'),
    (v_topic_id, '303: "Leukocyte Esterase" positive and "Nitrite" negative on UA suggests:', '["No infection", "Infection with a non-nitrite-producing organism (e.g., Enterococcus or S. saprophyticus) or sterile pyuria", "Normal urine", "Contamination"]', 1, 'Not all bacteria convert nitrate to nitrite.'),
    (v_topic_id, '304: "Sterile Pyuria" (WBCs in urine with no bacterial growth on standard culture) is a classic clue for:', '["E. coli UTI", "Renal Tuberculosis or Chlamydia", "Kidney stones", "Diabetes"]', 1, 'Standard cultures do not grow these organisms.'),
    (v_topic_id, '305: "Calcium Oxalate" crystals in the urine often have which characteristic shape?', '["Coffin-lid", "Envelope or Dumbbell", "Rhomboid", "Hexagonal"]', 1, 'They are the most common type of kidney stone.'),
    (v_topic_id, '306: "Struvite" (Triple Phosphate) crystals have a _____ shape and are associated with _____:', '["Envelope; acidic urine", "Coffin-lid; alkaline urine (Proteus infection)", "Hexagonal; cystinuria", "Needle; gout"]', 1, 'They form large "staghorn" calculi.'),
    (v_topic_id, '307: "Cystine" crystals in the urine are pathognomonic for Cystinuria and have a _____ shape.', '["Envelope", "Hexagonal", "Square", "Round"]', 1, 'This is a genetic defect in the transport of dibasic amino acids.'),
    (v_topic_id, '308: "Antinuclear Antibody" (ANA) has a very high _____ for Systemic Lupus Erythematosus (SLE).', '["Specificity", "Sensitivity (useful for ruling it OUT if negative)", "Cost", "Error rate"]', 1, 'A negative ANA makes SLE highly unlikely, but a positive one does not confirm it.'),
    (v_topic_id, '309: Which antibody is HIGHLY SPECIFIC for "Systemic Lupus Erythematosus" (SLE)?', '["ANA", "Anti-dsDNA and Anti-Smith", "Anti-Ro", "Anti-La"]', 1, 'These are rarely positive in other conditions.'),
    (v_topic_id, '310: "Anti-Histone" antibodies are the hallmark of:', '["Drug-Induced Lupus", "Graves disease", "Scleroderma", "Rheumatoid arthritis"]', 0, 'Commonly triggered by hydralazine, procainamide, or isoniazid.'),
    (v_topic_id, '311: "Anti-Centromere" antibodies are associated with:', '["Diffuse Scleroderma", "CREST Syndrome (Limited Scleroderma)", "SLE", "Sj\u00f6gren syndrome"]', 1, 'Calcinosis, Raynaud, Esophageal dysmotility, Sclerodactyly, Telangiectasia.'),
    (v_topic_id, '312: "Anti-Scl-70" (Anti-topoisomerase I) antibodies are associated with:', '["CREST", "Diffuse Systemic Sclerosis (Scleroderma)", "Dermatomyositis", "RA"]', 1, 'Associated with a higher risk of interstitial lung disease.'),
    (v_topic_id, '313: "Anti-Jo-1" antibodies are seen in:', '["SLE", "Polymyositis and Dermatomyositis", "Scleroderma", "Gout"]', 1, 'Often associated with "Mechanic''s hands" and lung disease.'),
    (v_topic_id, '314: "Anti-Ro (SSA)" and "Anti-La (SSB)" antibodies are diagnostic for:', '["Lupus only", "Sj\u00f6gren Syndrome", "RA", "Celiac disease"]', 1, 'They are also associated with neonatal lupus and heart block if present in pregnant women.'),
    (v_topic_id, '315: "Rheumatoid Factor" (RF) is an _____ antibody directed against the _____ portion of _____:', '["IgM; Fc; IgG", "IgG; Fab; IgM", "IgA; Fc; IgE", "IgE; Fab; IgG"]', 0, 'It is present in 70-80% of patients with RA but is not specific.'),
    (v_topic_id, '316: Which antibody is MORE SPECIFIC than RF for "Rheumatoid Arthritis"?', '["ANA", "Anti-Cyclic Citrullinated Peptide (Anti-CCP)", "Anti-DNA", "Anti-Smith"]', 1, 'Anti-CCP has a specificity of > 95%.'),
    (v_topic_id, '317: "c-ANCA" (PR3-ANCA) is the marker for:', '["Microscopic Polyangiitis", "Granulomatosis with Polyangiitis (Wegener''s)", "Eosinophilic Granulomatosis with Polyangiitis (Churg-Strauss)", "SLE"]', 1, 'Associated with upper/lower respiratory and renal involvement.'),
    (v_topic_id, '318: "p-ANCA" (MPO-ANCA) is associated with:', '["Microscopic Polyangiitis and Churg-Strauss", "Wegener''s", "Graves disease", "RA"]', 0, 'It shows a perinuclear staining pattern.'),
    (v_topic_id, '319: "Anti-Glomerular Basement Membrane" (Anti-GBM) antibodies are seen in:', '["Alport syndrome", "Goodpasture Syndrome (Pulmonary-Renal Syndrome)", "Nephrotic syndrome", "PSGN"]', 1, 'They attack the collagen in the basement membranes of lungs and kidneys.'),
    (v_topic_id, '320: "Complement" levels (C3, C4) are typically LOW in:', '["Active SLE and Post-Streptococcal Glomerulonephritis (PSGN)", "RA", "Scleroderma", "Osteoarthritis"]', 0, 'Complement is "consumed" during the formation of immune complexes.'),
    (v_topic_id, '321: "Rapid HIV" screening tests look for:', '["p24 antigen and HIV antibodies", "HIV DNA", "WBC count", "Viral weight"]', 0, 'The 4th generation p24/antibody combo is the current standard.'),
    (v_topic_id, '322: "HIV Viral Load" (PCR) is used to:', '["Screen for infection initially", "Monitor treatment response and detect early infection during the window period", "Check for immunity", "Identify the blood type"]', 1, 'It quantifies the number of RNA copies in the plasma.'),
    (v_topic_id, '323: "CD4 Count" in HIV is the primary indicator of:', '["Viral replication", "Immune status and risk for opportunistic infections", "Liver damage", "Drug toxicity"]', 1, 'Prophylaxis for PJP is usually started when CD4 < 200.'),
    (v_topic_id, '324: "Syphilis" screening traditionally uses a non-treponemal test like _____ or _____:', '["ELISA; PCR", "RPR; VDRL", "ANA; RF", "PSA; CEA"]', 1, 'These measure antibodies to cardiolipin/cholesterol/lecithin; they are sensitive but not specific.'),
    (v_topic_id, '325: A positive RPR must be confirmed with a specific treponemal test like:', '["VDRL", "FTA-ABS or TP-PA", "PCR", "Blood culture"]', 1, 'Treponemal tests remain positive for life, even after treatment.'),
    (v_topic_id, '326: "B-type Natriuretic Peptide" (BNP) levels are useful for monitoring _____ but can be "neutralized" by which class of drugs?', '["Statins", "ARNI (Sacubitril/Valsartan) - Sacubitril inhibits neprilysin, increasing BNP levels", "Beta-blockers", "Diuretics"]', 1, 'In patients on ARNIs, NT-proBNP should be used for monitoring instead of BNP.'),
    (v_topic_id, '327: "NT-proBNP" differs from BNP because it:', '["Has a longer half-life and is NOT affected by neprilysin inhibitors", "Is less sensitive", "Is found in the liver", "Is purely for lung disease"]', 0, 'It is a more stable marker in many clinical settings.'),
    (v_topic_id, '328: "Troponin" elevation in the absence of acute ischemia can be seen in:', '["Sepsis, Renal failure, and Pulmonary Embolism", "Normal exercise", "Eating sugar", "Taking aspirin"]', 0, 'Any condition that causes significant myocardial "stress" or decreased clearance can raise levels.'),
    (v_topic_id, '329: "D-dimer" is most useful in clinical practice to:', '["Confirm a DVT", "Rule out VTE (Venous Thromboembolism) in a low-probability patient", "Monitor warfarin", "Check for heart failure"]', 1, 'Its value lies in its high sensitivity and negative predictive value.'),
    (v_topic_id, '330: "Erythrocyte Sedimentation Rate" (ESR) > 100 mm/h is highly suggestive of:', '["Infection", "Temporal Arteritis, Polymyalgia Rheumatica, or Multiple Myeloma", "Simple cold", "Normal aging"]', 1, 'Extreme elevations are rare and prompt a search for specific systemic diseases.'),
    (v_topic_id, '331: "Blood Culture" - "Contamination" is suspected if which organism grows in ONLY one of two bottles?', '["S. aureus", "Coagulase-Negative Staphylococci (e.g., S. epidermidis)", "E. coli", "S. pneumoniae"]', 1, 'These are common skin commensals that can contaminate the draw.'),
    (v_topic_id, '332: A "Midstream Clean-Catch" urine sample is intended to minimize:', '["Pain", "Contamination from the distal urethra and skin", "Protein loss", "Glucose spikes"]', 1, 'The initial stream flushes out colonizing bacteria from the opening.'),
    (v_topic_id, '333: "HbA1c" of 6.0% is considered:', '["Normal", "Prediabetes (5.7% to 6.4%)", "Diabetes", "Hypoglycemia"]', 1, 'Increased risk for developing frank diabetes and cardiovascular disease.'),
    (v_topic_id, '334: "Hypomagnesemia" and "Hypocalcemia" are common complications of which procedure?', '["Blood transfusion (due to citrate anticoagulant binding the ions)", "X-ray", "Physical exam", "Lung biopsy"]', 0, 'Citrate in blood products chelates calcium and magnesium.'),
    (v_topic_id, '335: "Lactic Acid" should be measured in which type of blood for the most accuracy?', '["Arterial", "Venous (without using a tourniquet or clenching the fist)", "Capillary", "None of these"]', 1, 'Venous stasis from a tourniquet can falsely elevate lactate levels.'),
    (v_topic_id, '336: "Ammonia" samples must be:', '["Kept warm", "Placed on ice and analyzed immediately", "Stored for 24 hours", "Shaken"]', 1, 'Ammonia levels rise rapidly at room temperature due to cellular metabolism.'),
    (v_topic_id, '337: "Alpha-1 Antitrypsin" (AAT) level is low, but the definitive test for the genotype is:', '["PCR", "Protein Phenotyping (PI typing)", "X-ray", "Liver biopsy"]', 1, 'PI*ZZ is the most common genotype associated with severe disease.'),
    (v_topic_id, '338: "Sweat Chloride" > _____ mmol/L is diagnostic for Cystic Fibrosis in all ages.', '["20", "60", "40", "10"]', 1, 'Intermediate levels (30-59) require genetic testing.'),
    (v_topic_id, '339: "Fecal Occult Blood Test" (FOBT) or "FIT" are used to screen for:', '["Infection", "Asymptomatic Colorectal Cancer", "H. pylori", "Fat malabsorption"]', 1, 'The FIT (Immunochemical) test is more specific for human blood than the older guaiac test.'),
    (v_topic_id, '340: "Direct Bilirubin" is also known as _____ bilirubin.', '["Free", "Water-soluble (conjugated)", "Toxic", "Albumin-bound"]', 1, 'Because it is water-soluble, it can appear in the urine (bilirubinuria).'),
    (v_topic_id, '341: "Indirect Bilirubin" is also known as _____ bilirubin.', '["Conjugated", "Lipid-soluble (unconjugated)", "Urine", "Processed"]', 1, 'It is bound to albumin and cannot be filtered by the kidney.'),
    (v_topic_id, '342: "Urobilinogen" is absent from the urine in cases of:', '["Hemolysis", "Complete Bile Duct Obstruction", "Hepatitis", "Normal health"]', 1, 'Bilirubin cannot reach the gut to be converted into urobilinogen by bacteria.'),
    (v_topic_id, '343: "Urobilinogen" is HIGH in the urine in cases of:', '["Bile duct obstruction", "Hemolysis", "Renal failure", "Dehydration"]', 1, 'More bilirubin reaches the gut, leading to more urobilinogen being reabsorbed and excreted.'),
    (v_topic_id, '344: "Lactate Dehydrogenase" (LDH) has _____ isoenzymes.', '["2", "5", "10", "None"]', 1, 'LDH-1 and 2 are cardiac/RBC; LDH-4 and 5 are liver/muscle.'),
    (v_topic_id, '345: "Flipped LDH" pattern (LDH-1 > LDH-2) was historically used to diagnose:', '["Pneumonia", "Myocardial Infarction or Hemolysis", "Diabetes", "Stroke"]', 1, 'It is largely replaced by troponin for cardiac diagnosis.'),
    (v_topic_id, '346: "Serum Osmolar Gap" > 10 in a patient with HAGMA is most suggestive of:', '["DKA", "Toxic Alcohol Ingestion", "Lactic Acidosis", "Uremia"]', 1, 'The alcohols themselves create the osmolar gap before they are metabolized into the acids that create the anion gap.'),
    (v_topic_id, '347: "Reference Ranges" for labs are typically established using what percentage of the healthy population?', '["50%", "95% (mean +/- 2 standard deviations)", "99%", "100%"]', 1, 'This means 5% of healthy people will have a "statistically abnormal" result by definition.'),
    (v_topic_id, '348: "Sensitivity" of a test is its ability to correctly identify those _____ the disease.', '["Without", "With", "At risk for", "Cured of"]', 1, 'A highly sensitive test has few false negatives.'),
    (v_topic_id, '349: "Specificity" of a test is its ability to correctly identify those _____ the disease.', '["With", "Without", "Near", "After"]', 1, 'A highly specific test has few false positives.'),
    (v_topic_id, '350: Which of the following is the most important factor in lab interpretation?', '["The numbers on the page", "The clinical context and the patient''s history/exam", "The laboratory software", "The reference range"]', 1, 'Treat the patient, not the lab value.');
